-- MemTrace relational schema (postgresql). Generated by scripts/export_schema.py - do not edit by hand.

CREATE TABLE app_settings (
	key VARCHAR(64) NOT NULL, 
	value JSON NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (key)
);

CREATE TABLE rules (
	rule_id VARCHAR(64) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	default_severity VARCHAR(16) NOT NULL, 
	base_points INTEGER NOT NULL, 
	description TEXT NOT NULL, 
	attack_techniques JSON NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	PRIMARY KEY (rule_id)
);

CREATE TABLE users (
	id SERIAL NOT NULL, 
	username VARCHAR(64) NOT NULL, 
	full_name VARCHAR(128) NOT NULL, 
	password_hash VARCHAR(256) NOT NULL, 
	role VARCHAR(32) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_users_username ON users (username);

CREATE TABLE cases (
	id SERIAL NOT NULL, 
	case_number VARCHAR(32) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	investigator_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(investigator_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX ix_cases_case_number ON cases (case_number);

CREATE TABLE yara_rule_files (
	id SERIAL NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	stored_path VARCHAR(1024) NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	rule_names JSON NOT NULL, 
	builtin BOOLEAN NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	uploaded_by INTEGER, 
	uploaded_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(uploaded_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE memory_images (
	id SERIAL NOT NULL, 
	case_id INTEGER NOT NULL, 
	original_filename VARCHAR(255) NOT NULL, 
	stored_path VARCHAR(1024) NOT NULL, 
	size_bytes BIGINT NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	format_hint VARCHAR(32) NOT NULL, 
	validation_notes JSON NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	uploaded_by INTEGER, 
	uploaded_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	os_info JSON NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id) ON DELETE CASCADE, 
	FOREIGN KEY(uploaded_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_memory_images_case_id ON memory_images (case_id);
CREATE INDEX ix_memory_images_sha256 ON memory_images (sha256);

CREATE TABLE analysis_jobs (
	id SERIAL NOT NULL, 
	image_id INTEGER NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	stage VARCHAR(64) NOT NULL, 
	progress INTEGER NOT NULL, 
	options JSON NOT NULL, 
